/*
 * A085778  Primes whose reversal is a semiprime.
 * https://oeis.org/A085778
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 17, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  File:  a.c
 *
 *  Formula: a(n) is the n‑th prime whose decimal reversal is a semiprime.
 *  (No simple closed formula is known; the sequence is generated by
 *  incrementally scanning primes and testing the reversal.)
 */

/* ------------------------------------------------------------------ */
/*  Basic utilities                                                   */
/* ------------------------------------------------------------------ */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <math.h>

/*  Reverse the decimal digits of a 64‑bit unsigned integer.            */
static uint64_t reverse_uint64(uint64_t x)
{
    uint64_t r = 0;
    while (x > 0) {
        r = r * 10 + (x % 10);
        x /= 10;
    }
    return r;
}

/*  ---------------------------------------------------------------- */
/*  Prime storage and generator                                      */
/* ------------------------------------------------------------------ */

/*  A dynamic array of primes, held as uint64_t.
 *  We never remove primes, so a simple grow‑on‑need strategy works.  */
static uint64_t *primes      = NULL;
static size_t    primes_cnt  = 0;
static size_t    primes_cap  = 0;

/*  The last integer that was tested for primality.
 *  Once a prime is found, this value is set to that prime.          */
static uint64_t last_tested = 1;

/*  Allocate or grow the prime array to at least the required capacity. */
static void grow_primes(size_t needed)
{
    if (needed <= primes_cap)
        return;
    size_t new_cap = primes_cap ? primes_cap : 16;
    while (new_cap < needed)
        new_cap *= 2;
    uint64_t *tmp = (uint64_t *)realloc(primes, new_cap * sizeof(uint64_t));
    if (!tmp) abort();          /* OOM – not expected in test harness     */
    primes      = tmp;
    primes_cap  = new_cap;
}

/*  Generate the next prime after `last_tested` and append it to the table. */
static void generate_next_prime(void)
{
    if (primes_cnt == 0) {
        /* Initialise with the first prime. */
        last_tested = 2;
        grow_primes(1);
        primes[0] = 2;
        primes_cnt = 1;
        return;
    }

    for (;;) {
        /* Skip even numbers after 2. */
        if (last_tested == 2)
            last_tested = 3;
        else
            last_tested += 2;

        uint64_t candidate = last_tested;
        uint64_t root      = (uint64_t)sqrt((double)candidate) + 1;
        bool   is_prime    = true;

        for (size_t i = 0; i < primes_cnt && primes[i] <= root; ++i) {
            if (candidate % primes[i] == 0) {
                is_prime = false;
                break;
            }
        }

        if (is_prime) {
            grow_primes(primes_cnt + 1);
            primes[primes_cnt++] = candidate;
            return;
        }
    }
}

/*  Ensure that the prime table contains all primes up to `limit`.     */
static void ensure_primes_upto(uint64_t limit)
{
    if (primes_cnt == 0)
        generate_next_prime();      /* create first prime */

    while (primes[primes_cnt - 1] < limit)
        generate_next_prime();
}

/* ------------------------------------------------------------------ */
/*  Semiprime testing                                                */
/* ------------------------------------------------------------------ */

/*  Return true if n is a product of exactly two (not necessarily
 *  distinct) primes.  The routine is safe for all 64‑bit values.   */
static bool is_semiprime_uint64(uint64_t n)
{
    if (n < 4)
        return false;               /* smallest semiprime is 2*2 = 4    */

    int factor_cnt = 0;
    uint64_t rem    = n;

    uint64_t root = (uint64_t)sqrt((double)rem) + 1;
    ensure_primes_upto(root);

    for (size_t i = 0; i < primes_cnt && primes[i] * primes[i] <= rem; ++i) {
        uint64_t p = primes[i];
        if (rem % p == 0) {
            ++factor_cnt;
            rem /= p;
            if (rem % p == 0) {      /* count multiplicity once */
                ++factor_cnt;
                rem /= p;
            }
        }
        if (factor_cnt > 2)          /* early exit: cannot be semiprime */
            return false;
    }

    if (rem > 1)                      /* remaining prime factor */
        ++factor_cnt;

    return factor_cnt == 2;
}

/* ------------------------------------------------------------------ */
/*  Sequence table                                                   */
/* ------------------------------------------------------------------ */

static seq_t *term_tbl = NULL;   /* array of found sequence terms      */
static size_t term_cnt = 0;      /* number of terms stored             */
static size_t term_cap = 0;      /* current capacity of term_tbl       */
static size_t prime_itr = 0;     /* next prime index to test           */

/*  Re‑allocate term storage to at least `needed`.                   */
static void grow_terms(size_t needed)
{
    if (needed <= term_cap)
        return;
    size_t new_cap = term_cap ? term_cap : 8;
    while (new_cap < needed)
        new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(term_tbl, new_cap * sizeof(seq_t));
    if (!tmp) abort();          /* OOM – not expected                */
    term_tbl  = tmp;
    term_cap  = new_cap;
}

/* ------------------------------------------------------------------ */
/*  Main sequence function                                           */
/* ------------------------------------------------------------------ */

seq_t a(idx_t n)
{
    if (n == 0)                     /* undefined; harmless */
        return (seq_t)0;

    /* Generate terms until we have at least n of them. */
    while (term_cnt < (size_t)n) {
        /*  Make sure we have enough primes to test. */
        if (prime_itr >= primes_cnt)
            generate_next_prime();     /* expands prime table            */

        uint64_t p = primes[prime_itr++];
        uint64_t rev = reverse_uint64(p);

        if (is_semiprime_uint64(rev)) {
            grow_terms(term_cnt + 1);
            term_tbl[term_cnt++] = (seq_t)p;
        }
    }

    return term_tbl[n - 1];
}
